import json
from dataclasses import dataclass
from typing import Dict, List

@dataclass
class SalesInvoice:
    inv_number: str
    inv_date: str
    customer_name: str
    customer_gstin: str        # '' if unregistered
    supplier_state: str        # e.g., '29'
    place_of_supply: str       # e.g., '27'
    is_export_under_lut: bool
    hsn_code: str
    taxable_value: float
    gst_rate: float

class GSTR1Engine:
    @staticmethod
    def compile_gstr1(invoices: List[SalesInvoice]) -> Dict:
        table4_b2b = []
        table5_b2cl = []
        table6_exports = []
        table7_b2cs = []
        hsn_summary = {}

        tot_cgst = 0.0
        tot_sgst = 0.0
        tot_igst = 0.0

        for inv in invoices:
            is_inter = inv.supplier_state != inv.place_of_supply
            tax_val = inv.taxable_value * inv.gst_rate

            if inv.is_export_under_lut:
                tax_val = 0.0
                cgst, sgst, igst = 0.0, 0.0, 0.0
                table6_exports.append(inv)
            elif is_inter:
                cgst, sgst, igst = 0.0, 0.0, tax_val
            else:
                cgst, sgst, igst = tax_val / 2.0, tax_val / 2.0, 0.0

            tot_cgst += cgst
            tot_sgst += sgst
            tot_igst += igst

            # Classification into GSTR-1 Tables
            if not inv.is_export_under_lut:
                if inv.customer_gstin != '':
                    table4_b2b.append(inv)
                elif is_inter and inv.taxable_value > 250000.0:
                    table5_b2cl.append(inv)
                else:
                    table7_b2cs.append(inv)

            # HSN Table 12 Aggregation
            if inv.hsn_code not in hsn_summary:
                hsn_summary[inv.hsn_code] = {'taxable': 0.0, 'total_tax': 0.0}
            hsn_summary[inv.hsn_code]['taxable'] += inv.taxable_value
            hsn_summary[inv.hsn_code]['total_tax'] += tax_val

        return {
            'table_counts': {
                'table_4_b2b_count': len(table4_b2b),
                'table_5_b2c_large_count': len(table5_b2cl),
                'table_6_zero_rated_export_count': len(table6_exports),
                'table_7_b2c_small_count': len(table7_b2cs)
            },
            'electronic_liability_ledger_crystallized': {
                'gross_cgst_liability': round(tot_cgst, 2),
                'gross_sgst_liability': round(tot_sgst, 2),
                'gross_igst_liability': round(tot_igst, 2),
                'total_gross_output_tax': round(tot_cgst + tot_sgst + tot_igst, 2)
            },
            'table_12_hsn_summary': hsn_summary
        }

