import json
from dataclasses import dataclass
from typing import Dict, List

@dataclass
class PurchaseRegisterEntry:
    erp_inv_id: str
    vendor_gstin: str
    taxable_val: float
    cgst: float
    sgst: float
    igst: float
    goods_received: bool

@dataclass
class PortalGSTR2BEntry:
    portal_inv_id: str
    vendor_gstin: str
    taxable_val: float
    cgst: float
    sgst: float
    igst: float
    itc_available_flag: bool # False if Sec 16(4) breached or blocked

class InwardReconciliationEngine:
    @staticmethod
    def execute_reconciliation(pr_list: List[PurchaseRegisterEntry], gstr2b_list: List[PortalGSTR2BEntry]) -> Dict:
        gstr2b_lookup = {e.portal_inv_id: e for e in gstr2b_list}

        matched_itc = {'cgst': 0.0, 'sgst': 0.0, 'igst': 0.0}
        blocked_vendor_missing = {'cgst': 0.0, 'sgst': 0.0, 'igst': 0.0}
        ineligible_portal_flagged = {'cgst': 0.0, 'sgst': 0.0, 'igst': 0.0}
        audit_records = []

        for pr in pr_list:
            tot_pr_tax = pr.cgst + pr.sgst + pr.igst

            if pr.erp_inv_id not in gstr2b_lookup:
                # Missing in Portal: Vendor failed to file GSTR-1
                blocked_vendor_missing['cgst'] += pr.cgst
                blocked_vendor_missing['sgst'] += pr.sgst
                blocked_vendor_missing['igst'] += pr.igst
                status = 'BLOCKED: Absent from GSTR-2B. Vendor communication ticket triggered.'
                claimable = False
            else:
                p = gstr2b_lookup[pr.erp_inv_id]
                if not p.itc_available_flag:
                    ineligible_portal_flagged['cgst'] += pr.cgst
                    ineligible_portal_flagged['sgst'] += pr.sgst
                    ineligible_portal_flagged['igst'] += pr.igst
                    status = 'INELIGIBLE: Portal Part B (Sec 16(4) limitation or supplier default).'
                    claimable = False
                elif abs(pr.taxable_val - p.taxable_val) <= 1.0 and pr.goods_received:
                    matched_itc['cgst'] += pr.cgst
                    matched_itc['sgst'] += pr.sgst
                    matched_itc['igst'] += pr.igst
                    status = 'MATCHED: 100% Verified against GSTR-2B. Auto-populated in Table 4(A).'
                    claimable = True
                else:
                    status = 'VARIANCE: Invoice value mismatch or goods not physically received.'
                    claimable = False

            audit_records.append({
                'invoice_id': pr.erp_inv_id,
                'vendor': pr.vendor_gstin,
                'claimable_in_gstr3b': claimable,
                'audit_status': status
            })

        return {
            'reconciliation_summary': {
                'matched_claimable_itc': matched_itc,
                'blocked_vendor_missing_itc': blocked_vendor_missing,
                'portal_ineligible_flagged_itc': ineligible_portal_flagged,
                'total_verified_itc_pool': round(matched_itc['cgst'] + matched_itc['sgst'] + matched_itc['igst'], 2)
            },
            'audit_trail': audit_records
        }

